refentry.refsect1:
&reftitle.description;
mixedarray_find_key arrayarray callablecallback
array_find_key ले &array; को त्यस्तो पहिलो element को key return गर्दछ, जसका लागि दिइएको callback ले &true; return गर्छ। यदि कुनै मिल्दो element फेला परेन भने function ले &null; return गर्दछ।

  &reftitle.examples;

   array_find_key को उदाहरण


<?php
$array = [
    'a' => 'dog',
    'b' => 'cat',
    'c' => 'cow',
    'd' => 'duck',
    'e' => 'goose',
    'f' => 'elephant'
];

// Find the first animal with a name longer than 4 characters.
var_dump(array_find_key($array, function (string $value) {
    return strlen($value) > 4;
}));

// Find the first animal whose name begins with f.
var_dump(array_find_key($array, function (string $value) {
    return str_starts_with($value, 'f');
}));

// Find the first animal where the array key is the first symbol of the animal.
var_dump(array_find_key($array, function (string $value, $key) {
   return $value[0] === $key;
}));

// Find the first animal where the array key matching a RegEx.
var_dump(array_find_key($array, function ($value, $key) {
   return preg_match('/^([a-f])$/', $key);
}));
?>


   &example.outputs;


string(1) "e"
NULL
string(1) "c"
string(1) "a"
